import{B,C,read,circle,diagramStage}from'../ten-utils.js';
export default({g,p,extra,t})=>{let m=extra.mode??0,k=p[0];if(m===0){let f=k/100,yeast=extra.organism===1;circle(g,-.3,0,.5,C.green);g.sphere(-.3,0,0,.1,C.gold,B('Nucleus','केंद्रक'));circle(g,yeast?.2+.25*f:-.3+.85*f,yeast?-.3:0,yeast?.08+.22*f:.5,C.green);if(f>.5)g.sphere(yeast?.4:-.3+.85*f,yeast?-.3:0,0,.08,C.gold);return[read('Mode','विधि',yeast?B('Budding in yeast','यीस्ट में मुकुलन'):B('Binary fission in Amoeba','अमीबा में द्विखंडन')),read('Illustrative progress','सांकेतिक प्रगति',k,'%')]}
let names=m===1?[B('Pollen transfer','पराग का स्थानांतरण'),B('Pollen on stigma','वर्तिकाग्र पर पराग'),B('Pollen tube','पराग नलिका'),B('Fertilisation','निषेचन'),B('Seed and fruit formation','बीज और फल निर्माण')]:[B('Gametes','युग्मक'),B('Fertilisation in oviduct','अंडवाहिनी में निषेचन'),B('Embryo divisions','भ्रूण में विभाजन'),B('Implantation in uterus','गर्भाशय में आरोपण'),B('Foetal development','भ्रूण का विकास')];let pts=[[-1.3,-.4,0],[-.65,.2,0],[0,-.4,0],[.65,.2,0],[1.3,-.4,0]];diagramStage(g,pts,k,t,names);if(m===1){g.line([.65,.3,0],[.65,.9,0],C.green,4);circle(g,.65,.4,.3,C.pink)}return[read('Process stage','प्रक्रिया की अवस्था',names[k]),read('Important distinction','महत्वपूर्ण अंतर',m===1?B('Pollination is pollen transfer; fertilisation is fusion of gametes','परागण पराग का स्थानांतरण है; निषेचन युग्मकों का संलयन है'):B('Fertilisation normally occurs in the oviduct; implantation occurs in the uterine lining','निषेचन सामान्यतः अंडवाहिनी में; आरोपण गर्भाशय की परत में होता है'))]};
